def find_orfs(s, min_len=150):
    """Find ORFs >= min_len nt (50 aa) in all 3 frames of given strand."""
    orfs = []
    n = len(s)
    for frame in range(3):
        i = frame
        while i + 2 < n:
            if s[i:i+3] == "ATG":
                # find stop
                j = i
                while j + 2 < n and s[j:j+3] not in ("TAA","TAG","TGA"):
                    j += 3
                orf_len = j - i + 3  # include stop
                if orf_len >= min_len:
                    orfs.append((i+1, j+3, orf_len, s[i:j+3]))  # 1-based
                i = j + 3
            else:
                i += 3
    return orfs

