    'AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}

def rc(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

def find_orfs_plus(s, min_len=150):
    """Return ORFs as (plus_start, plus_end, strand, nt_seq) with proper coords."""
    results = []
    # forward strand
    for frame in range(3):
        i = frame
        while i + 2 < len(s):
            if s[i:i+3] == "ATG":
                j = i
                while j + 2 < len(s) and s[j:j+3] not in ("TAA","TAG","TGA"):
                    j += 3
                if j + 2 < len(s):  # found a stop
                    orf = s[i:j+3]
                    if len(orf) >= min_len:
                        results.append((i+1, j+3, "+", orf))
                    i = j + 3
                else:  # runs to end of sequence (partial)
                    orf = s[i:]
                    if len(orf) >= min_len:
                        results.append((i+1, len(s), "+", orf, "PARTIAL(no stop)"))
                    break
            else:
                i += 3
    # reverse strand
    r = rc(s)
    for frame in range(3):
        i = frame
        while i + 2 < len(r):
            if r[i:i+3] == "ATG":
                j = i
                while j + 2 < len(r) and r[j:j+3] not in ("TAA","TAG","TGA"):
                    j += 3
                if j + 2 < len(r):
                    orf = r[i:j+3]
                    if len(orf) >= min_len:
                        # convert to plus coords: rc pos i -> plus n-i ; rc pos j+2 -> plus n-(j+2)
                        results.append((n-(j+3)+1, n-i, "-", orf))
                    i = j + 3
                else:
                    orf = r[i:]
                    if len(orf) >= min_len:
                        results.append((n-len(r)+1, n-i, "-", orf, "PARTIAL(no stop)"))
                    break
            else:
                i += 3
    return results

orfs = find_orfs_plus(seq, 150)
print("=== All ORFs >= 150 nt (plus-strand 1-based coords) ===")
for item in sorted(orfs, key=lambda x: -len(x[3])):
